'use strict';
const state={sectionId:'demographics',answers:{},language:'en',audit:[],startedAt:new Date().toISOString(),report:null,heightSource:null,weightSource:null,demoMode:false};
let schema,pathways;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allQuestions=()=>schema.sections.flatMap(s=>s.questions);
const questionById=id=>allQuestions().find(q=>q.id===id);
const answer=id=>state.answers[id];
const isPositive=v=>Array.isArray(v)?v.length>0&&v.some(x=>!['No','Never','Never used','No known exposure','None','None known','Not sure','Unsure','Not applicable','Prefer not to say','Prefer not to answer','Not available'].includes(String(x))):v!==undefined&&v!==null&&v!==''&&!['No','Never','Never used','No known exposure','None','None known','Not sure','Unsure','Not applicable','Prefer not to say','Prefer not to answer','Not available','No previous assessment','No recommendation made','Genetic testing not performed'].includes(String(v));
