   add('oral_cavity',answerEvidence(['C005','C005-LOC','G-ORAL-LESION','C006','C006-SITE','C015','C015-LOC','PRIOR-ABNORMAL-TYPE'],'Persistent oral lesion, mouth/jaw lump, relevant bleeding/pain or previous oral abnormality reported'));

