   add('head_neck',answerEvidence(['C005','C005-LOC','G-THROAT','G-EAR','G-MOUTH-MOVEMENT','C010','C010-LOC','C011'],'Neck lump or persistent throat/voice/swallowing/ear/mouth-movement finding reported'));

