 if(bloodCough||persistentResp||breathing||chestPain||/lung|chest|pulmonary/i.test(val('INVESTIGATION-DETAIL'))&&prior)
   add('lung',answerEvidence(['C009','C009-NOW','C009-ASSOC','G-COUGH','C016','C015','C015-LOC','G-CHEST-PAIN','LU004'],'Unexplained respiratory symptom, haemoptysis, chest pain or relevant abnormal lung investigation reported'));

