 const chronicLiver=['Chronic liver disease','Cirrhosis','Hepatitis B','Hepatitis C','More than one'].includes(val('CHRONIC-LIVER'));
 const liverSymptoms=eq('G-JAUNDICE','Yes')||positive('LI002')||(upperPain&&(weight||bloating||appetite||eq('G-JAUNDICE','Yes')))||(chronicLiver&&(weight||bloating||appetite||upperPain))||(/liver|hepatic|bilirubin/i.test(val('INVESTIGATION-DETAIL'))&&prior);
 if(liverSymptoms) add('liver',answerEvidence(['G-JAUNDICE','LI002','C001','C012','C014','C015','C015-LOC','CHRONIC-LIVER','INVESTIGATION-DETAIL'],'Jaundice, liver-related symptom pattern or relevant liver investigation reported'));
 if(chronicLiver) risk('Liver surveillance review','Chronic liver disease, cirrhosis or hepatitis B/C history recorded; clinician-directed surveillance may be appropriate under applicable guidance. This is a risk/surveillance review, not a symptomatic cancer diagnosis.');
 if(eq('EN001','Yes')||eq('EN002','Yes')||eq('EN003','Yes, currently','Yes, previously')) risk('Endometrial risk-factor review','A relevant endometrial risk factor (such as PCOS, endometrial hyperplasia or menopausal hormone therapy) was recorded. Review it with a clinician; a risk factor alone does not establish cancer and does not automatically activate a symptomatic pathway.');

