   add('prostate',answerEvidence(['U001','U002','U003','U004','U005','C008','PR001','PR002','PR003','PR007','INVESTIGATION-DETAIL'],'Relevant urinary/prostate symptom, blood in semen, PSA/examination abnormality or prior prostate investigation with prostate present'));

