 if(isUnder18()&&(eq('PED-HEADACHE','Yes')||eq('PED-NEURO','Yes'))) add('paediatric_cns',answerEvidence(['PED-HEADACHE','PED-NEURO'],'New persistent headache or neurological warning symptom reported in a patient under 18'));
