function translateChrome(){const t={en:{language:'Language',tag:'Integrated cancer assessment workflow · presentation build 1.3.8',notice:'<strong>Research / demonstration build.</strong> This rule-based application is not a diagnostic tool and does not calculate a validated probability of cancer. The prototype index is unvalidated. Do not use it to order tests or delay care. Emergency symptoms require immediate local emergency services.',route:'Two-stage assessment',route2:'General intake → independent safety gateway → conditional pathway activation → clinician-directed summary',back:'← Back',next:'Continue →',review:'Review assessment',footer:'ONCOGUIDE · Integrated presentation build v1.3.8 · Local-only demo · Clinical rules, scoring and translations require qualified review before deployment'},hi:{language:'भाषा',tag:'एकीकृत कैंसर मूल्यांकन कार्यप्रवाह · प्रस्तुति संस्करण',notice:'<strong>अनुसंधान / प्रदर्शन संस्करण।</strong> यह नियम-आधारित ऐप निदान नहीं करता और कैंसर की प्रमाणित संभावना नहीं बताता। प्रोटोटाइप सूचकांक मान्य नहीं है। केवल इसके आधार पर जाँच न कराएँ और चिकित्सा सहायता में देरी न करें। आपात लक्षणों में तुरंत स्थानीय आपात सेवा लें।',route:'दो-चरणीय मूल्यांकन',route2:'सामान्य जानकारी → स्वतंत्र सुरक्षा जाँच → सशर्त पथ सक्रियण → चिकित्सक-निर्देशित सारांश',back:'← पीछे',next:'आगे →',review:'मूल्यांकन की समीक्षा',footer:'ONCOGUIDE · प्रस्तुति संस्करण · स्थानीय डेमो · उपयोग से पहले चिकित्सकीय नियमों, स्कोरिंग और अनुवादों की समीक्षा आवश्यक'},mr:{language:'भाषा',tag:'एकात्मिक कर्करोग मूल्यांकन कार्यप्रवाह · सादरीकरण आवृत्ती',notice:'<strong>संशोधन / प्रात्यक्षिक आवृत्ती.</strong> हे नियमाधारित ॲप निदान करत नाही आणि कर्करोगाची प्रमाणित शक्यता मोजत नाही. प्रोटोटाइप निर्देशांक प्रमाणित नाही. यावरूनच तपासण्या करू नका किंवा वैद्यकीय मदत घेण्यास विलंब करू नका. आपत्कालीन लक्षणे असल्यास त्वरित स्थानिक आपत्कालीन सेवा घ्या.',route:'दोन-टप्प्यांचे मूल्यांकन',route2:'सामान्य माहिती → स्वतंत्र सुरक्षा तपासणी → सशर्त मार्ग सक्रिय करणे → डॉक्टरांच्या मार्गदर्शनाखाली सारांश',back:'← मागे',next:'पुढे →',review:'मूल्यांकन तपासा',footer:'ONCOGUIDE · सादरीकरण आवृत्ती · स्थानिक डेमो · वापरापूर्वी वैद्यकीय नियम, गुणांकन व भाषांतरांचे पुनरावलोकन आवश्यक'},gu:{language:'ભાષા',tag:'સંકલિત કેન્સર મૂલ્યાંકન કાર્યપ્રવાહ · પ્રસ્તુતિ આવૃત્તિ',notice:'<strong>સંશોધન / પ્રદર્શન આવૃત્તિ.</strong> આ નિયમ આધારિત એપ નિદાન કરતી નથી અને કેન્સરની પ્રમાણિત સંભાવના ગણતી નથી. પ્રોટોટાઇપ સૂચકાંક માન્ય નથી. માત્ર તેના આધારે તપાસ કરાવશો નહીં અથવા તબીબી મદદમાં વિલંબ કરશો નહીં. તાત્કાલિક લક્ષણોમાં સ્થાનિક ઇમરજન્સી સેવાનો સંપર્ક કરો.',route:'બે તબક્કાનું મૂલ્યાંકન',route2:'સામાન્ય માહિતી → સ્વતંત્ર સલામતી તપાસ → શરતી માર્ગ સક્રિયકરણ → તબીબના માર્ગદર્શન હેઠળ સારાંશ',back:'← પાછા',next:'આગળ →',review:'મૂલ્યાંકન સમીક્ષા',footer:'ONCOGUIDE · પ્રસ્તુતિ આવૃત્તિ · સ્થાનિક ડેમો · ઉપયોગ પહેલાં ક્લિનિકલ નિયમો, સ્કોરિંગ અને અનુવાદોની સમીક્ષા જરૂરી'}}[state.language]||{};const langEl=$('.lang');if(langEl&&langEl.firstChild)langEl.firstChild.textContent=t.language+' ';const tagline=document.querySelector('.top p');if(tagline)tagline.textContent=t.tag;const notice=document.querySelector('.notice');if(notice)notice.innerHTML=t.notice;const rs=$('#routingSummary');if(rs){rs.querySelector('strong').textContent=t.route;rs.querySelector('span').textContent=t.route2;}if($('#prev'))$('#prev').textContent=t.back;if($('#next'))$('#next').textContent=t.next;if($('#reviewBtn'))$('#reviewBtn').textContent=t.review;const foot=document.querySelector('footer');if(foot)foot.textContent=t.footer;}
function renderQuestion(q){let v=answer(q.id);if(v===undefined)v=q.type==='multiselect'?[]:'';const id='q-'+q.id;let ctrl='';const req=q.required?'<span class="required"> *</span>':'';const help=q.help?`<p class="help">${esc(q.help)}</p>`:'';
 if(q.type==='readonly')ctrl=`<input id="${id}" readonly value="${esc(v)}" aria-readonly="true">`;
 else if(q.type==='select')ctrl=`<select id="${id}" data-q="${q.id}" ${q.required?'required':''}><option value="">— Select —</option>${q.options.map(o=>`<option value="${esc(o)}" ${String(v)===o?'selected':''}>${esc(optLabel(o))}</option>`).join('')}</select>`;
 else if(q.type==='multiselect')ctrl=`<select id="${id}" data-q="${q.id}" multiple size="${Math.min(6,Math.max(3,q.options.length))}">${q.options.map(o=>`<option value="${esc(o)}" ${(Array.isArray(v)&&v.includes(o))?'selected':''}>${esc(optLabel(o))}</option>`).join('')}</select><small class="small">Use Ctrl (Windows) or Command (Mac) to select multiple options.</small>`;
 else if(q.type==='date-dmy') {const d=dateFromDMY(v);ctrl=`<div class="date-pair"><input id="${id}" data-q="${q.id}" type="text" placeholder="DD/MM/YYYY" inputmode="numeric" value="${esc(v)}" ${q.required?'required':''}><input aria-label="Choose date" data-date-for="${q.id}" type="date" value="${d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:''}"></div>`;}
 else {const typ=q.type==='number'?'number':'text';const disabled=(q.id==='D-AGE'&&!!dateFromDMY(answer('D-DOB')))||(q.id==='D-HEIGHT-FT'||q.id==='D-HEIGHT-IN')&&state.heightSource==='cm'||q.id==='D-HEIGHT-CM'&&state.heightSource==='ft'||q.id==='D-WEIGHT-LB'&&state.weightSource==='kg'||q.id==='D-WEIGHT-KG'&&state.weightSource==='lb'||(q.id==='D-ACT-MIN'||q.id==='D-ACT-VIG')&&answer('D-ACTIVITY')!=="Can't say";const min=q.min!==undefined?`min="${q.min}"`:'';const max=q.max!==undefined?`max="${q.max}"`:'';const step=q.step!==undefined?`step="${q.step}"`:(typ==='number'?'step="1"':'');ctrl=`<input id="${id}" data-q="${q.id}" type="${typ}" ${min} ${max} ${step} value="${esc(v)}" ${q.required?'required':''} ${disabled?'disabled':''} ${typ==='text'&&q.id!=='D-NAME'?'autocomplete="off"':''}>`;}
 return `<div class="field"><label for="${id}">${esc(trLabel(q))}${req}</label><div>${ctrl}</div>${help}</div>`;
}
function clearHiddenAnswers(){let changed=true,guard=0;while(changed&&guard++<8){changed=false;for(const q of allQuestions()){if((q.showIf||q.showIfAll||q.showIfAny||anatomyQuestion(q.id))&&!visibleQuestion(q)&&state.answers[q.id]!==undefined){delete state.answers[q.id];changed=true;}}const visibleIds=new Set(getVisibleSections().map(s=>s.id));for(const sec of schema.sections){if(!visibleIds.has(sec.id)){for(const q of sec.questions){if(state.answers[q.id]!==undefined){delete state.answers[q.id];changed=true;}}}}}}
function loadDemo(kind){if(!confirm('Load synthetic demonstration data? This replaces current answers. No real patient data should be used.'))return;state.answers={};state.audit=[];state.report=null;state.demoMode=true;$('#results').hidden=true;$('#review').hidden=true;$('#questionnaire').hidden=false;$('#sectionNav').hidden=false;state.heightSource='cm';state.weightSource='kg';const base={'D-NAME':'SYNTHETIC DEMO — NOT A REAL PATIENT','D-ETHNICITY':'Asian','D-AGE':kind==='pediatric'?'7':'42','D-SEX':kind==='pediatric'?'Female':'Male','D-ANATOMY':kind==='pediatric'?'Yes':'No','D-UTERUS':kind==='pediatric'?'Yes':'No','D-OVARIES':kind==='pediatric'?'Yes':'No','D-PROSTATE':kind==='pediatric'?'No':'Yes','D-HEIGHT-CM':kind==='pediatric'?'125':'172','D-WEIGHT-KG':kind==='pediatric'?'25':'76','D-ACTIVITY':'Moderate','FH-CANCER':'No','FH-MULTIPLE':'No','PREV-CANCER':'No','PRIOR-ABNORMAL':'No','PRIOR-FOLLOWUP':'No recommendation made','INVESTIGATION':'No','T-STATUS':'Never used','A-STATUS':'Never','OR001':'Never','HPV-RESULT':'No','HPV-VAX':'No','D-HPV-VAX':'No','R-HPV-VAX':'No','OCC-EXPOSURE':['None known'],'CHRONIC-LIVER':'No','CHRONIC-DISEASE':['None'],'IMMUNOSUPPRESS':'No','C001':'No','C002':'No','C003':'No','C004':'No','C005':'No','C006':'No','C007':'No','C008':'No','C009':'No','C010':'No','C011':'No','C012':'No','C013':'No','C014':'No','C015':'No','C016':'No','G-COUGH':'No','G-JAUNDICE':'No','G-ORAL-LESION':'No','G-BREAST-CHANGE':['No'],'G-ABDOMINAL-UPPER':'No','G-THROAT':'No','G-EAR':'No','G-MOUTH-MOVEMENT':'No','G-VOMIT-BLOOD':'No','G-CHEST-PAIN':'No','U001':'No','U002':'No','U003':'No','U004':'No','U005':'No','PED-HEADACHE':'No','PED-NEURO':'No','PED-BONE':'No','PED-ABD':'No','PED-EYE':'No','PED-TESTICLE':'No'};Object.assign(state.answers,base);if(kind==='adult'){Object.assign(state.answers,{'C005':'Yes','C005-LOC':'Neck','C005-DUR':'More than 6 weeks ago','C005-GROW':'Yes','C005-PAIN':'No','G-THROAT':'Yes, more than 3 weeks','C011':'Persistent','C011-DUR':'More than 3 weeks'});state.sectionId='redflags';}else if(kind==='pediatric'){Object.assign(state.answers,{'PED-EYE':'Yes','PED-ABD':'No','PED-BONE':'No','PED-NEURO':'No','PED-HEADACHE':'No','PED-TESTICLE':'Not applicable'});state.sectionId='pediatric_flags';}else if(kind==='colorectal'){Object.assign(state.answers,{'C007':'Bright-red blood','C007-REPEAT':'Repeatedly','C013':'Persistent constipation','C013-DUR':'More than 4 weeks'});state.sectionId='redflags';}else if(kind==='blackstool'){Object.assign(state.answers,{'D-AGE':'58','C007':'Black tar-like stools','C007-REPEAT':'Repeatedly','C007-PLACE':'Mixed with stool'});state.sectionId='redflags';}else{Object.assign(state.answers,{'C016':'Sudden or severe','G-CHEST-PAIN':'Yes, severe/new'});state.sectionId='redflags';}state.audit.push({at:new Date().toISOString(),event:'synthetic_demo_loaded',scenario:kind});updateDerived();clearHiddenAnswers();render();}
function render(){translateChrome();const sections=getVisibleSections();if(!sections.length)return;let idx=sections.findIndex(s=>s.id===state.sectionId);if(idx<0){state.sectionId=sections[0].id;idx=0;}const sec=sections[idx];$('#sectionNav').innerHTML=sections.map((s,i)=>`<button type="button" class="${s.id===sec.id?'active':''}" data-id="${esc(s.id)}">${esc(tTitle(s))}</button>`).join('');$('#sectionNav').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.sectionId=b.dataset.id;render()});const qs=sec.questions.filter(visibleQuestion);const breastGuide=sec.id==='pathway_breast'?`<details class="breast-self-exam"><summary><span class="info-dot" aria-hidden="true">i</span> Breast self-examination guide</summary><p><strong>Visual examination</strong></p><ul><li>Stand in front of a mirror and look for a new change in size, shape or contour.</li><li>Look for dimpling, puckering, scaling, redness or swelling.</li><li>Check for a new nipple inversion, position change or unexpected discharge.</li></ul><p><strong>Tactile examination (palpation)</strong></p><ul><li>Using the pads of your fingers, gently cover the entire breast area, underarms/lymph-node areas, upper chest from the collarbone to below the breasts, and from the armpit toward the breastbone.</li><li>Use a consistent pattern to cover the whole area. Each area can be felt in three passes using light, medium and firm pressure to notice tissue at different depths. Do not press hard enough to cause pain.</li><li>If you menstruate, choose a time when breast tenderness is usually lower (often several days after the period). Otherwise, choose the same date each month if this helps you remember changes.</li></ul><img
  class="breast-guide-image"
  src="./assets/Self%20Breast%20Examination.jpg"
  alt="Illustrated breast self-examination guide"
><p class="small"><strong>Important:</strong> Breast self-examination is not a substitute for recommended screening or a clinician’s assessment, and it cannot rule out cancer. Contact a clinician about a new lump, persistent change, skin/nipple change or unexpected discharge. Seek urgent care for severe or rapidly worsening symptoms.</p></details>`:''; $('#questions').innerHTML=`<fieldset><legend>${esc(tTitle(sec))}</legend>${breastGuide}${qs.length?qs.map(renderQuestion).join(''):'<p class="small">No additional questions are required in this section based on the answers recorded.</p>'}</fieldset>`;$('#questions').querySelectorAll('[data-q]').forEach(el=>{el.addEventListener('change',onAnswer);if(el.tagName==='INPUT'&&['text','number'].includes(el.type))el.addEventListener('input',onInput);});$('#questions').querySelectorAll('[data-date-for]').forEach(el=>el.addEventListener('change',e=>{const id=e.target.dataset.dateFor;if(e.target.value){const [y,m,d]=e.target.value.split('-');state.answers[id]=`${d}/${m}/${y}`;const textEl=$('#q-'+id);if(textEl)textEl.value=state.answers[id];state.audit.push({at:new Date().toISOString(),event:'answer_changed',question_id:id,source:'calendar'});updateDerived();clearHiddenAnswers();syncDerivedInputs();updateLiveStatus();}}));$('#prev').disabled=idx===0;$('#next').hidden=idx===sections.length-1;$('#reviewBtn').hidden=idx!==sections.length-1;$('#progress').textContent=`Section ${idx+1} of ${sections.length} · ${Object.keys(state.answers).length} answers recorded`;$('#review').hidden=true;$('#results').hidden=true;updateDerived();updateLiveStatus();}
function onInput(e){const id=e.target.dataset.q;if(!id)return;const q=questionById(id);if(!q||q.type==='multiselect')return;if(id==='D-DOB'){const formatted=formatDMYInput(e.target.value);if(e.target.value!==formatted){e.target.value=formatted;try{e.target.setSelectionRange(formatted.length,formatted.length);}catch(_){}}state.answers[id]=formatted;}else state.answers[id]=e.target.value;if(id==='D-HEIGHT-CM')state.heightSource=e.target.value?'cm':null;if(id==='D-HEIGHT-FT'||id==='D-HEIGHT-IN')state.heightSource=(state.answers['D-HEIGHT-FT']||state.answers['D-HEIGHT-IN'])?'ft':null;if(id==='D-WEIGHT-KG')state.weightSource=e.target.value?'kg':null;if(id==='D-WEIGHT-LB')state.weightSource=e.target.value?'lb':null;if(['D-HEIGHT-CM','D-HEIGHT-FT','D-HEIGHT-IN','D-WEIGHT-KG','D-WEIGHT-LB','D-DOB','D-AGE','D-ACT-MIN','D-ACT-VIG','R-LMP'].includes(id))updateDerived();syncDerivedInputs();updateLiveStatus();}
function syncDerivedInputs(){const ids=['D-HEIGHT-FT','D-HEIGHT-IN','D-HEIGHT-CM','D-WEIGHT-LB','D-WEIGHT-KG','D-BMI','D-BMI-CATEGORY','D-AGE','D-AGE-DETAIL','D-ACTIVITY-DERIVED','R-GESTATION','R-EDD'];for(const id of ids){const el=$('#q-'+id);if(!el)continue;if(document.activeElement!==el)el.value=answer(id)??'';}const dobValid=!!dateFromDMY(answer('D-DOB'));const ageEl=$('#q-D-AGE');if(ageEl)ageEl.disabled=dobValid;for(const [id,disabled] of [['D-HEIGHT-FT',state.heightSource==='cm'],['D-HEIGHT-IN',state.heightSource==='cm'],['D-HEIGHT-CM',state.heightSource==='ft'],['D-WEIGHT-LB',state.weightSource==='kg'],['D-WEIGHT-KG',state.weightSource==='lb']]){const el=$('#q-'+id);if(el)el.disabled=disabled;}for(const id of ['D-ACT-MIN','D-ACT-VIG']){const el=$('#q-'+id);if(el)el.disabled=answer('D-ACTIVITY')!=="Can't say";}}
function onAnswer(e){const id=e.target.dataset.q;if(!id)return;const q=questionById(id);if(q.type==='multiselect'){let selected=Array.from(e.target.selectedOptions).map(o=>o.value);const exclusive=['No','Not sure','Unsure','None','None known','None known exposure','Not applicable','Prefer not to say','Prefer not to answer'];const pickedExclusive=selected.filter(v=>exclusive.includes(v));if(pickedExclusive.length){selected=selected.length===1?selected:selected.filter(v=>!exclusive.includes(v));if(!selected.length)selected=[pickedExclusive[pickedExclusive.length-1]];}state.answers[id]=selected;}else state.answers[id]=e.target.value;if(id==='D-ACTIVITY'&&e.target.value!=="Can't say"){delete state.answers['D-ACT-MIN'];delete state.answers['D-ACT-VIG'];}if(id==='D-HEIGHT-CM')state.heightSource=e.target.value?'cm':null;if(id==='D-HEIGHT-FT'||id==='D-HEIGHT-IN')state.heightSource=(state.answers['D-HEIGHT-FT']||state.answers['D-HEIGHT-IN'])?'ft':null;if(id==='D-WEIGHT-KG')state.weightSource=e.target.value?'kg':null;if(id==='D-WEIGHT-LB')state.weightSource=e.target.value?'lb':null;state.audit.push({at:new Date().toISOString(),event:'answer_changed',question_id:id});if(['D-HEIGHT-CM','D-HEIGHT-FT','D-HEIGHT-IN','D-WEIGHT-KG','D-WEIGHT-LB','D-DOB','D-AGE','D-ACTIVITY','D-ACT-MIN','D-ACT-VIG','R-LMP','R-CURRENT-PREGNANT'].includes(id))updateDerived();clearHiddenAnswers();if(['text','number','date-dmy'].includes(q.type)){syncDerivedInputs();updateLiveStatus();}else render();}
function updateDerived(){const a=state.answers;const cm=Number(a['D-HEIGHT-CM']),ft=Number(a['D-HEIGHT-FT']),inch=Number(a['D-HEIGHT-IN']);if(state.heightSource==='cm'&&cm>0){a['D-HEIGHT-FT']=String(Math.floor(cm/30.48));a['D-HEIGHT-IN']=String(Math.round((cm/2.54-Math.floor(cm/30.48)*12)*10)/10);}else if(state.heightSource==='cm'&&cm<=0){a['D-HEIGHT-FT']='';a['D-HEIGHT-IN']='';}else if(state.heightSource==='ft'&&(ft>0||inch>0)){a['D-HEIGHT-CM']=String(Math.round((ft*12+inch)*2.54*10)/10);}else if(state.heightSource==='ft'){a['D-HEIGHT-CM']='';}const kg=Number(a['D-WEIGHT-KG']),lb=Number(a['D-WEIGHT-LB']);if(state.weightSource==='kg'&&kg>0)a['D-WEIGHT-LB']=String(Math.round(kg*2.20462262*10)/10);else if(state.weightSource==='kg')a['D-WEIGHT-LB']='';else if(state.weightSource==='lb'&&lb>0)a['D-WEIGHT-KG']=String(Math.round(lb/2.20462262*10)/10);else if(state.weightSource==='lb')a['D-WEIGHT-KG']='';const h=Number(a['D-HEIGHT-CM']),w=Number(a['D-WEIGHT-KG']);if(h>0&&w>0){a['D-BMI']=(w/((h/100)**2)).toFixed(1);const ag=age();if(ag!==null&&ag<18)a['D-BMI-CATEGORY']='Paediatric BMI must be interpreted using an age- and sex-specific growth reference; not classified here';else if(+a['D-BMI']<18.5)a['D-BMI-CATEGORY']='Underweight (adult WHO classification)';else if(+a['D-BMI']<25)a['D-BMI-CATEGORY']='Normal range (adult WHO classification)';else if(+a['D-BMI']<30)a['D-BMI-CATEGORY']='Overweight (adult WHO classification)';else if(+a['D-BMI']<35)a['D-BMI-CATEGORY']='Obesity class I (adult classification)';else if(+a['D-BMI']<40)a['D-BMI-CATEGORY']='Obesity class II (adult classification)';else a['D-BMI-CATEGORY']='Obesity class III (adult classification)';}else{a['D-BMI']='';a['D-BMI-CATEGORY']='Enter height and weight';}
 const dob=dateFromDMY(a['D-DOB']);if(dob){const ageObj=ageFromDOB(dob);a['D-AGE']=String(ageObj.y);a['D-AGE-DETAIL']=`${ageObj.y} years, ${ageObj.m} months, ${ageObj.days} days`;}else a['D-AGE-DETAIL']='';
 if(a['D-ACTIVITY']==="Can't say"){const mod=Number(a['D-ACT-MIN'])||0,vig=Number(a['D-ACT-VIG'])||0,ag=age();if(ag!==null&&ag<18)a['D-ACTIVITY-DERIVED']=((mod+2*vig)/7>=60?'Meets 60 min/day average reference':'Below 60 min/day average reference');else {const equivalent=mod+2*vig;a['D-ACTIVITY-DERIVED']=equivalent>=150?'Meets adult 150 min/week moderate-equivalent reference':equivalent>0?'Below adult 150 min/week moderate-equivalent reference':'No activity minutes recorded';}}else a['D-ACTIVITY-DERIVED']='';const lmp=dateFromDMY(a['R-LMP']);if(lmp&&a['R-CURRENT-PREGNANT']==='Yes'){const today=new Date();const days=Math.floor((today-lmp)/86400000);if(days>=0&&days<315){a['R-GESTATION']=`${Math.floor(days/7)} weeks, ${days%7} days`;const edd=new Date(lmp.getTime()+280*86400000);a['R-EDD']=`${String(edd.getDate()).padStart(2,'0')}/${String(edd.getMonth()+1).padStart(2,'0')}/${edd.getFullYear()}`;}else{a['R-GESTATION']='Unable to calculate from the entered date';a['R-EDD']='Unable to calculate from the entered date';}}else{a['R-GESTATION']='';a['R-EDD']='';}}
function updateLiveStatus(){const ev=activation(),sf=safetyFlags();let el=$('#liveStatus');if(!el){el=document.createElement('section');el.id='liveStatus';el.className='live-status';$('#questionnaire').prepend(el);}el.innerHTML=`<strong>Live routing preview</strong><div class="small">${ev.active.length} pathway(s) currently activated · ${ev.riskReviews.length} separate risk/screening review(s) · ${sf.length} safety flag(s)</div>${sf.map(x=>`<div class="mini-flag ${x.level==='EMERGENCY'?'emergency':''}"><b>${esc(x.level)}</b> — ${esc(x.message)}</div>`).join('')}`;}
function validateSection(){const sec=getVisibleSections().find(s=>s.id===state.sectionId);if(!sec)return true;const missing=sec.questions.filter(q=>q.required&&visibleQuestion(q)&&!answer(q.id));if(missing.length){alert('Please complete required fields: '+missing.map(trLabel).join('; '));return false;}if(sec.id==='demographics'){const dob=dateFromDMY(answer('D-DOB'));if(!dob&&(!answer('D-AGE')||!Number.isFinite(Number(answer('D-AGE'))))){alert('Enter age in years or a valid date of birth in DD/MM/YYYY.');return false;}if(!answer('D-HEIGHT-CM')||!answer('D-WEIGHT-KG')){alert('Height and weight are required to calculate BMI.');return false;}}return true;}
function moveNext(){if(!validateSection())return;const sections=getVisibleSections(),idx=sections.findIndex(s=>s.id===state.sectionId);if(idx<sections.length-1){state.sectionId=sections[idx+1].id;render();}else showReview();}
function validateAllRequired(){const missing=[];for(const sec of getVisibleSections()){for(const q of sec.questions){if(q.required&&visibleQuestion(q)&&!answer(q.id))missing.push({section:sec.id,label:trLabel(q)});}}if(missing.length){const first=missing[0];state.sectionId=first.section;render();alert('Complete required fields before generating the report: '+missing.map(x=>x.label).join('; '));return false;}const dob=dateFromDMY(answer('D-DOB'));const a=Number(answer('D-AGE'));if(!Number.isFinite(a)||a<0||a>120){state.sectionId='demographics';render();alert('Enter a valid age in years (or a valid date of birth to calculate it).');return false;}if(answer('D-DOB')&&!dateFromDMY(answer('D-DOB'))){state.sectionId='demographics';render();alert('Enter the date of birth in DD/MM/YYYY format, or clear the field if unknown.');return false;}const h=Number(answer('D-HEIGHT-CM')),w=Number(answer('D-WEIGHT-KG'));if(!Number.isFinite(h)||h<20||h>260||!Number.isFinite(w)||w<1||w>500){state.sectionId='demographics';render();alert('Enter a plausible height (20–260 cm) and weight (1–500 kg).');return false;}return true;}
function showReview(){if(!validateSection()||!validateAllRequired())return;const ev=activation(),sf=safetyFlags(),sections=getVisibleSections();$('#questionnaire').hidden=true;$('#sectionNav').hidden=true;$('#review').hidden=false;$('#review').innerHTML=`<div class="panel"><h2>Review assessment</h2><p>Review recorded answers before generating the report. Unknown or unasked responses remain distinct from “No”.</p>${sections.map(s=>`<h3>${esc(tTitle(s))}</h3><div class="grid">${s.questions.filter(visibleQuestion).filter(q=>answer(q.id)!==undefined&&answer(q.id)!=='').map(q=>`<div><strong>${esc(trLabel(q))}</strong><div>${esc(Array.isArray(answer(q.id))?answer(q.id).join(', '):answer(q.id))}</div></div>`).join('')}</div>`).join('')}<h3>Routing preview</h3><p>${ev.active.length} pathways activated; ${ev.riskReviews.length} separate risk reviews; ${sf.length} safety flags.</p><div class="actions"><button id="editBtn">Edit answers</button><button class="primary" id="reportBtn">Generate assessment report</button></div></div>`;$('#editBtn').onclick=()=>{state.sectionId='demographics';$('#questionnaire').hidden=false;$('#sectionNav').hidden=false;render()};$('#reportBtn').onclick=generateReport;}
