function pathwayIndex(id){if(String(id).startsWith('paediatric_'))return {points:null,max:100,coverage:0,coveragePct:0,domains:[],interpretation:'Paediatric route is rule-based only; no paediatric tumour score is enabled.'};const specs=pathwaySpecs[id]||[],used=new Set();let points=0,coverage=0;const domains=specs.map(dom=>{const original=dom[3]||[],unique=original.filter(qid=>!used.has(qid));const adjusted=[dom[0],dom[1],dom[2],unique,dom[4]];const status=unique.length?domainStatus(adjusted,id):{level:null,detail:'Same source variable already accounted for in an earlier pathway domain; not counted twice.'};unique.forEach(qid=>used.add(qid));if(status.level!==null){coverage+=dom[1];points+=responsePoints(dom[1],status.level);}return {name:dom[0],max:dom[1],level:status.level,points:status.level===null?null:responsePoints(dom[1],status.level),detail:status.detail,variables_considered:unique};});const complete=coverage===100;return {points:complete?Math.round(points*10)/10:null,observedSubtotal:Math.round(points*10)/10,max:100,coverage,coveragePct:Math.round(coverage),domains,complete,interpretation:complete?'Experimental descriptive pathway index only; all weighted domains were assessable. No clinical risk category or urgency threshold is assigned.':'Total not calculated because one or more weighted domains remain unassessed. The observed subtotal is not comparable with a complete 100-point index.'};}
function mealPatternSummary(){const ids=['D001','D002','D003','D004','D005','D006','D007','D008','D009','D010','D011','D012'];const rows=ids.map(id=>{const q=questionById(id);return {id,label:q?.label?.en||id,response:answer(id)??'Not answered'};});const answered=rows.filter(x=>x.response!=='Not answered'&&x.response!==''&&!(Array.isArray(x.response)&&!x.response.length)).length;return {items:rows,coverage:answered+'/'+rows.length+' dietary items answered',disclaimer:'Descriptive dietary context only. These answers do not establish a diagnosis or validated cancer probability.'};}
function generateReport(){const ev=activation(),sf=safetyFlags(),now=new Date();const id='OG-'+now.toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+Math.random().toString(36).slice(2,6).toUpperCase();const general=generalRiskIndex();const meals=mealPatternSummary();const visibleSections=getVisibleSections();const missingInformation=visibleSections.flatMap(sec=>sec.questions.filter(q=>visibleQuestion(q)&&(!answer(q.id)||answer(q.id)==='Not sure'||answer(q.id)==='Unsure'||answer(q.id)==='Prefer not to say'||answer(q.id)==='Prefer not to answer')).map(q=>({section:sec.title?.en||sec.id,question_id:q.id,label:q.label?.en||q.id,status:answer(q.id)||'Not answered'})));state.audit.push({at:now.toISOString(),event:'report_generated',assessment_id:id});const report={assessment_id:id,created_at:now.toISOString(),application_version:schema.version,questionnaire_version:schema.version,pathway_rules_version:pathways.version,validation_status:'Not clinically validated',language:state.language,synthetic_demo:state.demoMode,answers:state.answers,activated_pathways:ev.active.map(p=>({...p,assessment_priority_index:pathwayIndex(p.id),next_step:pathways.pathways.find(x=>x.id===p.id)?.next_step,investigation_guidance:pathways.pathways.find(x=>x.id===p.id)?.investigation_guidance,marker_guidance:pathways.pathways.find(x=>x.id===p.id)?.marker_guidance})),risk_reviews:ev.riskReviews,safety_flags:sf,general_risk_factor_burden_index:general,dietary_history_summary:meals,missing_information:missingInformation,score_disclaimer:'No cancer probability is calculated. Prototype-only signal index is not a probability of cancer and is not validated for clinical decisions. Do not use a score to order imaging, tumour markers, IHC, biopsy or treatment.',audit_events:state.audit};state.report=report;$('#review').hidden=true;$('#results').hidden=false;$('#results').innerHTML=`<div class="panel report-head"><div><span class="eyebrow">ONCOGUIDE · Assessment report</span>${state.demoMode?'<div class="flag"><strong>SYNTHETIC DEMO CASE — NOT A REAL PATIENT</strong></div>':''}<h2>Assessment summary</h2><p><strong>Assessment ID:</strong> ${esc(id)}</p><p><strong>Created:</strong> ${esc(now.toLocaleString())}</p></div><div class="report-actions"><button id="printBtn">Print / Save PDF</button><button id="jsonBtn">Export JSON</button><button id="restartBtn">New assessment</button></div></div><div class="flag"><strong>Clinical safety notice.</strong> This research prototype does not diagnose cancer or estimate a validated probability of future cancer. Its experimental general risk-factor burden index and pathway assessment-priority indices are not validated clinical risk scores. Do not delay care or order investigations based on this report alone.</div><div class="score-grid"><div class="score-card"><span>General risk-factor burden index</span><strong>${general.points===null?'Not calculated':general.points+'/100'}</strong><small>${general.coveragePct}% of weighted domains assessed; experimental, non-predictive${general.points===null?`; observed subtotal ${general.observedSubtotal} points; total withheld because coverage is incomplete`:''}</small></div><div class="score-card"><span>Pathways activated</span><strong>${ev.active.length}</strong><small>Each activation includes a rule-based reason</small></div><div class="score-card"><span>Safety flags</span><strong>${sf.length}</strong><small>Independent of the index</small></div><div class="score-card"><span>Risk reviews</span><strong>${ev.riskReviews.length}</strong><small>Separate from symptomatic pathways</small></div></div>${sf.length?`<h3>Safety gateway</h3>${sf.map(s=>`<div class="flag ${s.level==='EMERGENCY'?'emergency':''}"><strong>${esc(s.level)} · ${esc(s.id)}</strong><p>${esc(s.message)}</p></div>`).join('')}`:''}<h3>Dietary history summary</h3><p>${esc(meals.coverage)}. ${esc(meals.disclaimer)}</p><div class="grid">${meals.items.map(m=>`<div class="path-result"><strong>${esc(m.label)}</strong><div>${esc(Array.isArray(m.response)?m.response.join(', '):m.response)}</div></div>`).join('')}</div><h3>General risk-factor index: coverage and contributors</h3><p><strong>Interpretation:</strong> ${esc(general.interpretation)} This index describes selected recorded exposures/background factors only; it is not a probability of developing cancer. Unknown domains are not assumed absent.</p><details><summary>General index domain breakdown</summary><ul>${general.domains.map(d=>`<li><strong>${esc(d.name)}:</strong> ${d.assessed?`${d.points}/${d.max} points`:'Not scored / unknown'} — ${esc(d.detail)}</li>`).join('')}</ul></details><h3>Clinical review principles — independent of score</h3><div class="path-result"><p><strong>Emergency or urgent safety flag:</strong> follow the displayed safety advice immediately; do not wait for a score or report.</p><p><strong>New, persistent, progressive or otherwise concerning symptom:</strong> arrange clinical assessment based on the symptom, duration, severity, age and clinical context, even if the prototype index is low.</p><p><strong>Screening:</strong> use applicable evidence-based age-, anatomy- and risk-based screening guidance; this prototype does not determine screening eligibility.</p><p><strong>Investigations:</strong> a qualified clinician selects tests based on history, examination and relevant findings. Tumour markers, biopsy, histopathology, IHC and molecular tests are not automatically indicated by any score.</p><p class="small"><strong>Important:</strong> neither the general index nor any pathway index is a validated triage threshold, cancer probability or clinical decision rule.</p></div><h3>Activated pathways</h3>${ev.active.length? ev.active.map(p=>`<div class="path-result"><div class="path-title"><h4>${esc(p.name)}</h4><span class="pill">${esc(p.level.replace('_',' '))}</span></div><p><strong>Activation reason(s)</strong></p><ul>${p.reason.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p><strong>Pathway assessment index (prototype):</strong> ${pathwayIndex(p.id).points===null?(String(p.id).startsWith('paediatric_')?'Not scored — paediatric route is rule-based only':'Not calculated — incomplete domain coverage'):pathwayIndex(p.id).points+'/100'} <span class="small">(${pathwayIndex(p.id).coveragePct}% of weighted domains assessed; prototype only, not probability${pathwayIndex(p.id).points===null&&!String(p.id).startsWith('paediatric_')?`; observed subtotal ${pathwayIndex(p.id).observedSubtotal}; total withheld`:''})</span></p><p><strong>Prototype interpretation:</strong> ${esc(pathwayIndex(p.id).interpretation)}</p><details><summary>Scoring domains and missing information</summary><ul>${pathwayIndex(p.id).domains.map(d=>`<li><strong>${esc(d.name)}:</strong> ${d.points===null?'Not scored / unknown':`${d.points}/${d.max} points`} — ${esc(d.detail)}</li>`).join('')}</ul></details><p><strong>Next step:</strong> ${esc(pathways.pathways.find(x=>x.id===p.id)?.next_step||'Clinician-directed assessment.')}</p>${pathways.pathways.find(x=>x.id===p.id)?.investigation_guidance?`<p><strong>Clinician-directed initial investigation options:</strong> ${esc(pathways.pathways.find(x=>x.id===p.id).investigation_guidance)}</p>`:''}${pathways.pathways.find(x=>x.id===p.id)?.marker_guidance?`<details class="marker-guidance" open><summary><strong>Pathway-specific tumour-marker, pathology and IHC considerations</strong></summary><p><strong>Serum/other tumour markers:</strong> ${esc(pathways.pathways.find(x=>x.id===p.id).marker_guidance.tumour_markers||'No routine marker panel; clinician-directed only.')}</p><p><strong>Histopathology / IHC markers:</strong> ${esc(pathways.pathways.find(x=>x.id===p.id).marker_guidance.pathology_ihc||'Pathologist-selected after tissue diagnosis.')}</p><p><strong>Molecular / genetic testing:</strong> ${esc(pathways.pathways.find(x=>x.id===p.id).marker_guidance.molecular||'Only if indicated after specialist review.')}</p><p class="small">These are conditional considerations for a qualified clinician/pathologist, not a test order. A score alone does not justify tumour markers, biopsy, IHC or molecular testing.</p></details>`:''}</div>`).join(''):'<div class="panel"><strong>No configured pathway trigger was met.</strong><p>This does not rule out cancer or another illness. Persistent, new or worsening symptoms should be discussed with a qualified clinician.</p></div>'}${ev.riskReviews.length?`<h3>Separate risk and screening reviews</h3>${ev.riskReviews.map(r=>`<div class="path-result"><h4>${esc(r.name)}</h4><p>${esc(r.reason)}</p></div>`).join('')}`:''}<h3>Relevant recorded context</h3><div class="grid">${[['Age',answer('D-AGE')],['Sex',answer('D-SEX')],['BMI',answer('D-BMI')],['BMI interpretation',answer('D-BMI-CATEGORY')],['Tobacco',answer('T-STATUS')],['Alcohol',answer('A-STATUS')],['Family history',answer('FH-CANCER')],['Prior abnormality',answer('PRIOR-ABNORMAL')],['Relevant anatomy','Cervix: '+(anatomyValue('D-ANATOMY')||'Not recorded')+'; uterus: '+(anatomyValue('D-UTERUS')||'Not recorded')+'; ovaries: '+(anatomyValue('D-OVARIES')||'Not recorded')+'; prostate: '+(anatomyValue('D-PROSTATE')||'Not recorded')]].filter(x=>x[1]!==undefined&&x[1]!==null&&x[1]!=='').map(x=>`<div><strong>${esc(x[0])}</strong><div>${esc(x[1])}</div></div>`).join('')}</div><h3>Missing and uncertain information</h3><p class="small">Blank fields are not assumed to be negative. “Not sure”, “not applicable” and “prefer not to answer” are retained as entered.</p>${missingInformation.length?`<details open><summary>${missingInformation.length} unanswered or uncertain field(s)</summary><ul>${missingInformation.slice(0,100).map(x=>`<li><strong>${esc(x.section)} · ${esc(x.question_id)}:</strong> ${esc(x.label)} — ${esc(x.status)}</li>`).join('')}</ul>${missingInformation.length>100?`<p>Showing the first 100 of ${missingInformation.length} fields.</p>`:''}</details>`:'<p>No unanswered or explicitly uncertain visible fields were found.</p>'}<p class="small">Clinician review should consider completeness and the context of all symptoms, histories and prior investigations.</p><h3>Audit trail</h3><p>${state.audit.length} recorded application events. The local-only prototype does not transmit this assessment to a server.</p><details><summary>View all recorded answers</summary><pre>${esc(JSON.stringify(state.answers,null,2))}</pre></details><details><summary>View audit events</summary><pre>${esc(JSON.stringify(report.audit_events,null,2))}</pre></details>`;$('#printBtn').onclick=()=>window.print();$('#jsonBtn').onclick=()=>{const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`${id}.json`;a.click();URL.revokeObjectURL(u);};$('#restartBtn').onclick=()=>{if(confirm('Start a new assessment? The current local assessment will be cleared from this page.')){state.answers={};state.audit=[];state.sectionId='demographics';state.report=null;state.heightSource=null;state.weightSource=null;state.demoMode=false;$('#results').hidden=true;$('#questionnaire').hidden=false;$('#sectionNav').hidden=false;render();}};}
async function init(){[schema,pathways]=await Promise.all([fetch('data/questionnaire.json').then(r=>{if(!r.ok)throw new Error('Questionnaire file failed to load');return r.json()}),fetch('data/pathways.json').then(r=>{if(!r.ok)throw new Error('Pathway file failed to load');return r.json()})]);$('#language').addEventListener('change',e=>{state.language=e.target.value;render()});for(const b of document.querySelectorAll('[data-demo]'))b.addEventListener('click',()=>loadDemo(b.dataset.demo));$('#prev').onclick=()=>{const ss=getVisibleSections(),idx=ss.findIndex(s=>s.id===state.sectionId);if(idx>0){state.sectionId=ss[idx-1].id;render()}};$('#next').onclick=moveNext;$('#reviewBtn').onclick=showReview;render();}
document.addEventListener('DOMContentLoaded',()=>init().catch(e=>{console.error(e);document.querySelector('main').insertAdjacentHTML('afterbegin',`<div class="flag"><strong>Application could not start.</strong> ${esc(e.message)}. Ensure the data folder and JSON files are present, then reload.</div>`)}));
